import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.WFmvnizL.js";const r="/assets/1_en_US.C4PWStdw.png",n="/assets/2_en_US.BAO_NUBp.png",i="/assets/3_en_US.aOskB-Uk.png",d="/assets/4_en_US.DRtJQ44N.png",c="/assets/5_en_US.OUB2jK0W.png",l="/assets/6_en_US.B0-QS4kt.png",y=JSON.parse('{"title":"Built-in backup and restore","description":"Use the encrypted backup and restore built into Nezha Monitoring Dashboard - configure S3-compatible storage (Cloudflare R2 as an example), keep the backup password and recovery key safe, schedule backups with retention, download, and restore on the same or a new host.","frontmatter":{"description":"Use the encrypted backup and restore built into Nezha Monitoring Dashboard - configure S3-compatible storage (Cloudflare R2 as an example), keep the backup password and recovery key safe, schedule backups with retention, download, and restore on the same or a new host.","outline":"deep"},"headers":[],"relativePath":"en_US/guide/backup.md","filePath":"en_US/guide/backup.md","lastUpdated":1795785361000}'),h={name:"en_US/guide/backup.md"};function p(u,e,b,g,f,k){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="built-in-backup-and-restore" tabindex="-1">Built-in backup and restore <a class="header-anchor" href="#built-in-backup-and-restore" aria-label="Permalink to &quot;Built-in backup and restore&quot;">​</a></h1><p>Dashboard can back up its own data from the admin panel and upload it to S3-compatible storage (AWS S3, Cloudflare R2, MinIO, and others). Backups are taken while the dashboard keeps running, and files are encrypted before upload. You can restore a backup from storage or from an uploaded file, also on a freshly installed dashboard.</p><p><strong>Where to find it:</strong> sign in as an administrator, click your avatar → System settings → the <strong>Backup</strong> tab. Only administrators can use it, and API tokens cannot call the backup API.</p><div class="tip custom-block"><p class="custom-block-title">Supported versions</p><p>This feature requires Dashboard v2.8.0 or later. For earlier versions, use the <a href="/en_US/guide/q5.html">manual migration, backup, and restore</a> method.</p></div><h2 id="what-a-backup-contains" tabindex="-1">What a backup contains <a class="header-anchor" href="#what-a-backup-contains" aria-label="Permalink to &quot;What a backup contains&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Included</th><th>Not included</th></tr></thead><tbody><tr><td>The dashboard database (users, servers, services, alerts, tasks, notifications, DDNS, and all other settings)</td><td>Monitoring time-series data (TSDB)</td></tr><tr><td><code>data/config.yaml</code></td><td>Deployment files such as Compose files, reverse proxy configuration, certificates, and systemd/OpenRC service files</td></tr><tr><td></td><td>The settings of the backup feature itself (<code>data/backup.yaml</code>)</td></tr></tbody></table><p>To keep TSDB history or deployment files, back them up separately or use the <a href="/en_US/guide/q5.html">manual method</a>.</p><p>Backup files use the <code>.nzbak</code> extension. They are only staged temporarily in the data directory and removed after upload, so Docker deployments need no extra volume.</p><h2 id="first-time-setup" tabindex="-1">First-time setup <a class="header-anchor" href="#first-time-setup" aria-label="Permalink to &quot;First-time setup&quot;">​</a></h2><p>The Backup tab guides you through three steps in order: <strong>S3 storage → backup password → schedule</strong>. Backups are available once storage and the password are set up.</p><p><img src="'+r+'" alt="First-time setup"></p><h3 id="_1-configure-s3-storage" tabindex="-1">1. Configure S3 storage <a class="header-anchor" href="#_1-configure-s3-storage" aria-label="Permalink to &quot;1. Configure S3 storage&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Endpoint</td><td>The storage service URL. It must start with <code>https://</code> and must not contain a path.</td></tr><tr><td>Bucket</td><td>The bucket that holds the backups. Create it beforehand.</td></tr><tr><td>Region</td><td>The region. If your provider has no regions, follow its documentation (use <code>auto</code> for R2).</td></tr><tr><td>Key prefix</td><td>Defaults to <code>nezha-backup/</code>, which is also used when the field is empty. Letters, digits, <code>/</code>, <code>_</code>, and <code>-</code> only. <strong>Dashboards sharing one bucket must use different prefixes</strong>, otherwise retention cleanup deletes each other&#39;s backups.</td></tr><tr><td>Path-style addressing</td><td>On by default. Turn it off only if the service supports nothing but virtual-hosted <code>bucket.endpoint</code> addressing.</td></tr><tr><td>Access Key ID / Secret Access Key</td><td>The access key. The secret is never shown again after saving and must be entered again when the endpoint or bucket changes.</td></tr></tbody></table><p>During first-time setup you must pass <strong>Test connection</strong> before saving; when changing an existing configuration, testing before saving is still recommended. The test writes a temporary object under the prefix, reads it back, and deletes it, so it needs at least permission to read, write, and delete objects. The backup list and retention cleanup also list the objects under the prefix, so for regular use the key needs permission to list objects as well.</p><h4 id="example-cloudflare-r2" tabindex="-1">Example: Cloudflare R2 <a class="header-anchor" href="#example-cloudflare-r2" aria-label="Permalink to &quot;Example: Cloudflare R2&quot;">​</a></h4><ol><li>In the Cloudflare dashboard, open <strong>R2</strong> and create a bucket, for example <code>nezha-backup</code>.</li><li>Under <strong>Manage API tokens</strong> in R2, create an API token with <strong>Object Read &amp; Write</strong> permission, scoped to this bucket only. Note the <strong>Access Key ID</strong>, the <strong>Secret Access Key</strong>, and the S3 endpoint shown on the page.</li><li>Fill in the Backup tab: <ul><li>Endpoint: <code>https://&lt;ACCOUNT_ID&gt;.r2.cloudflarestorage.com</code></li><li>Bucket: <code>nezha-backup</code></li><li>Region: <code>auto</code></li><li>Key prefix: keep the default <code>nezha-backup/</code> or change it as needed</li><li>Path-style addressing: keep it on (the default); R2 supports both addressing styles</li></ul></li><li>Click <strong>Test connection</strong>, then save once it passes.</li></ol><p><img src="'+n+'" alt="R2 storage filled in, connection test passed"></p><p>Do not use an account-wide token with full permissions; object read and write on this one bucket is all the token needs.</p><h3 id="_2-set-the-backup-password-and-save-the-recovery-key" tabindex="-1">2. Set the backup password and save the recovery key <a class="header-anchor" href="#_2-set-the-backup-password-and-save-the-recovery-key" aria-label="Permalink to &quot;2. Set the backup password and save the recovery key&quot;">​</a></h3><p>The backup password must be at least 12 characters. Setting it also asks for your login password (accounts that sign in only through OAuth must have signed in within the last 10 minutes), because whoever sets the backup password can decrypt every later backup. When you set it, the dashboard creates a key pair:</p><ul><li>Backups are encrypted to the public key, so scheduled backups run without the password.</li><li>The private key is stored only protected by the backup password; the password itself is never stored in plain text.</li><li>A <strong>recovery key</strong> is created at the same time and shown only once. You can copy it or download it as a <code>.txt</code> file, and must tick &quot;I have stored the recovery key safely&quot; before closing the dialog. It can replace the password to restore every backup of the same key.</li></ul><p><img src="'+i+'" alt="Save the recovery key"></p><div class="danger custom-block"><p class="custom-block-title">Keep them safe</p><p>If you forget the backup password and do not have the recovery key, the backups <strong>cannot be restored</strong> - nobody can decrypt them.</p><ul><li>Store the backup password in a password manager.</li><li>Keep the recovery key offline and separate from the backup files.</li><li>Do not keep the recovery key in the same bucket as the backups.</li></ul></div><p><strong>Change password:</strong> keeps the same key and only changes the password that protects the private key. New backups use the new password; older backups open with the old password, or with the new one on this dashboard.</p><p><strong>Reset password:</strong> creates a new key. Use it only if the password is lost or may have leaked. Afterwards, earlier backups are marked <strong>Old key</strong> in the list and can only be restored with the old password or the old recovery key. Resetting asks you to type <code>RESET</code> to confirm and verifies your login password like setting it. Before resetting, make sure you still have one of them, or no longer need those backups.</p><h3 id="_3-scheduled-backups-and-retention" tabindex="-1">3. Scheduled backups and retention <a class="header-anchor" href="#_3-scheduled-backups-and-retention" aria-label="Permalink to &quot;3. Scheduled backups and retention&quot;">​</a></h3><ul><li>The schedule uses a 6-field cron expression (seconds first), in the same time zone as scheduled tasks. The default <code>0 0 3 * * *</code> runs every day at 03:00.</li><li><strong>Scheduled backups to keep</strong> defaults to 7 and can be set from 1 to 100. Scheduled backups beyond that number are deleted automatically after a new scheduled backup completes.</li><li>Retention <strong>only removes scheduled backups</strong>. Manual backups are never deleted automatically; the last 3 &quot;Before restore&quot; backups are kept.</li><li>Failed uploads are retried automatically; if a backup still fails, it is shown as &quot;Failed&quot; in the list together with the reason.</li></ul><h2 id="manual-backups-and-downloads" tabindex="-1">Manual backups and downloads <a class="header-anchor" href="#manual-backups-and-downloads" aria-label="Permalink to &quot;Manual backups and downloads&quot;">​</a></h2><p>Click <strong>Back up now</strong> in the backup list. The list is read from the configured bucket and shows each backup&#39;s creation time, size, trigger (Manual, Scheduled, Before restore), status, dashboard version, and SHA-256.</p><p><img src="'+d+'" alt="Backup list"></p><p>Click <strong>Download</strong> to save the <code>.nzbak</code> file locally. Downloads go through the dashboard, so the storage address and keys are never exposed. The downloaded file stays encrypted; you can keep it offline and restore it later by uploading it.</p><p>Select backups you no longer need and delete them. Deleted backups cannot be recovered.</p><h2 id="restore" tabindex="-1">Restore <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Restore&quot;">​</a></h2><p>A restore replaces the current database and configuration and then restarts the dashboard, signing out every user. It has two steps, and the first one changes nothing.</p><div class="warning custom-block"><p class="custom-block-title">The dashboard must run under a supervisor</p><p>After a restore is applied, the dashboard exits and swaps in the data on its next start. The official installation methods (<code>restart: always</code> for Docker, <code>Restart=always</code> for systemd, and <code>supervise-daemon</code> for OpenRC) all restart it automatically. If you run it yourself, make sure the process is restarted when it exits.</p></div><h3 id="step-1-check-the-backup" tabindex="-1">Step 1: Check the backup <a class="header-anchor" href="#step-1-check-the-backup" aria-label="Permalink to &quot;Step 1: Check the backup&quot;">​</a></h3><ul><li><strong>From the list:</strong> click <strong>Restore</strong> next to a backup.</li><li><strong>From a file:</strong> click <strong>Restore from file</strong> and choose a <code>.nzbak</code> file (up to 256 MiB).</li></ul><p>Enter the backup password, or switch to the recovery key, then click <strong>Check backup</strong>. The dashboard downloads and verifies the backup: checksum, decryption, contents, origin, version compatibility, database integrity, and the presence of an administrator account.</p><p><img src="'+c+'" alt="Check the backup"></p><p>The check also lists what to be aware of, for example:</p><ul><li>Agents added after the backup will go offline.</li><li>API tokens and OAuth grants revoked after the backup become valid again.</li><li>TSDB data is not restored and stays as it is.</li><li>The origin cannot be verified (the backup was not made by this dashboard).</li></ul><p>Some warnings must be acknowledged with <strong>I understand and want to continue</strong> before you can proceed. The check is valid for 10 minutes; after that, run it again.</p><h3 id="step-2-confirm-and-apply" tabindex="-1">Step 2: Confirm and apply <a class="header-anchor" href="#step-2-confirm-and-apply" aria-label="Permalink to &quot;Step 2: Confirm and apply&quot;">​</a></h3><p>Enter the backup password (or recovery key) again, the last 6 characters of the backup name, and your login password. Accounts that only sign in with OAuth and have no local password must have signed in within the last 10 minutes.</p><p><img src="'+l+'" alt="Confirm and apply"></p><p>After you click <strong>Replace current data and restart</strong>:</p><ol><li>If storage and the backup password are set up, the dashboard first backs up the current data, kept as a &quot;Before restore&quot; backup.</li><li>The dashboard exits, restarts, and swaps in the backup data before opening the database.</li><li>The page shows the restart progress and takes you to the sign-in page when the dashboard is back. Sign in with an account <strong>from the backup</strong>.</li></ol><p>If the start fails with a database migration error, an unavailable port or TLS certificate, or if the process exits midway, the dashboard rolls back to the data from before the restore. The result of the last restore (succeeded, or failed and rolled back) is shown at the top of the Backup tab.</p><p>To prevent online password guessing, each user can run at most 5 checks or applies within 15 minutes. Every backup and restore operation is recorded in <code>backup-audit.log</code> in the data directory.</p><h3 id="restore-on-a-new-host" tabindex="-1">Restore on a new host <a class="header-anchor" href="#restore-on-a-new-host" aria-label="Permalink to &quot;Restore on a new host&quot;">​</a></h3><p>Use this when moving to another server or when the original host is gone:</p><ol><li><a href="/en_US/guide/dashboard.html">Install Dashboard</a> on the new host, at a version no older than the backup (see the version rules below), and sign in with the default administrator created by the installation.</li><li>Choose how to restore: <ul><li><strong>You have the backup file:</strong> upload the <code>.nzbak</code> file under &quot;Restore from a backup file&quot; on the Backup tab. <strong>Storage and a password do not need to be set up first.</strong></li><li><strong>The backup is only in storage:</strong> <a href="#_1-configure-s3-storage">configure S3 storage</a> with the original bucket and prefix first, then restore from the list.</li></ul></li><li>Enter the original backup password or recovery key and complete both steps. Because the new host has a different key, the check reports that the origin cannot be verified; acknowledge it once you are sure the file is trustworthy. While backups are not set up on the new host, no pre-restore backup is taken, and the page says so.</li><li>Sign in with your original account. <code>config.yaml</code> is restored as well, including the agents&#39; connection secret, so agents reconnect on their own as long as they can still reach the original address; if the address changed, update DNS or the agents&#39; connection address.</li><li><strong>The backup settings are not restored.</strong> Configure storage, the backup password, and the schedule again on the new host. Setting a password creates a new key, so the backups already in storage are marked &quot;Old key&quot;; they can still be restored with the original password or recovery key.</li></ol><div class="warning custom-block"><p class="custom-block-title">Listening address and certificates</p><p>After the restore, the dashboard uses the <code>config.yaml</code> from the backup. At start, the effective listening address and port must be bindable on the new host, and with TLS enabled the effective certificate and private key files must be readable; otherwise the start fails and rolls back. A port or certificate path that differs from the original host is not a problem in itself; prepare the new host accordingly, for example by placing the certificate at the same path or adjusting the Docker port mapping.</p></div><p>Once the new host is live, stop the old dashboard so that the two do not run tasks or send notifications at the same time. If the old dashboard keeps running and uses the same bucket, give the two dashboards different prefixes.</p><h2 id="compatibility-and-version-rules" tabindex="-1">Compatibility and version rules <a class="header-anchor" href="#compatibility-and-version-rules" aria-label="Permalink to &quot;Compatibility and version rules&quot;">​</a></h2><p>The check compares the core version <code>X.Y.Z</code> of the backup with the current dashboard:</p><table tabindex="0"><thead><tr><th>Case</th><th>Result</th></tr></thead><tbody><tr><td>The backup is from an older version</td><td>Restores. The database schema is upgraded at start, and settings missing from an older <code>config.yaml</code> use their defaults; a failed upgrade rolls back.</td></tr><tr><td>Same version</td><td>Restores.</td></tr><tr><td>Same core version, different build (different version suffix)</td><td>Needs an acknowledgement. Builds can differ in database changes; continue only if you know the difference is safe.</td></tr><tr><td>Versions cannot be compared (for example a development build)</td><td>Needs an acknowledgement.</td></tr><tr><td>The backup is from a newer core version</td><td><strong>Refused.</strong> Upgrade the dashboard to at least the backup&#39;s version first, then restore.</td></tr></tbody></table><p>Backup files carry a format version. A dashboard refuses formats it does not recognize instead of trying to read them.</p><h2 id="configure-storage-with-environment-variables" tabindex="-1">Configure storage with environment variables <a class="header-anchor" href="#configure-storage-with-environment-variables" aria-label="Permalink to &quot;Configure storage with environment variables&quot;">​</a></h2><p>The S3 storage fields can also be set with environment variables, for example to inject them from a container orchestrator or secret manager:</p><table tabindex="0"><thead><tr><th>Environment variable</th><th>Field</th></tr></thead><tbody><tr><td><code>NZ_BACKUP_S3_ENDPOINT</code></td><td>Endpoint</td></tr><tr><td><code>NZ_BACKUP_S3_BUCKET</code></td><td>Bucket</td></tr><tr><td><code>NZ_BACKUP_S3_REGION</code></td><td>Region</td></tr><tr><td><code>NZ_BACKUP_S3_PREFIX</code></td><td>Key prefix</td></tr><tr><td><code>NZ_BACKUP_S3_ACCESS_KEY_ID</code></td><td>Access Key ID</td></tr><tr><td><code>NZ_BACKUP_S3_SECRET_ACCESS_KEY</code></td><td>Secret Access Key</td></tr></tbody></table><p>Fields set by an environment variable are shown as &quot;Set by an environment variable&quot; and cannot be changed in the admin panel. When the secret comes from an environment variable, the endpoint and bucket are read-only as well, so the secret cannot be sent to another address entered in the admin panel. The other backup settings are kept in a separate <code>backup.yaml</code> in the data directory (mode 0600), not in <code>config.yaml</code>. These names do not follow the <a href="/en_US/configuration/environment.html">environment variable naming rules</a> of <code>config.yaml</code> fields; use them exactly as listed above.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>How is this different from backing up the data directory by hand?</strong> Built-in backups need no downtime, are encrypted and uploaded to off-site storage automatically, and restores are verified and roll back on failure. They cover only the dashboard itself. Use the <a href="/en_US/guide/q5.html">manual method</a> to also move TSDB data or deployment files, or on dashboard versions without this feature.</p><p><strong>Agents are offline after a restore?</strong> Agents added after the backup do not exist in the backup data and must be added again. Other agents reconnect automatically; if the dashboard address changed, update the agents&#39; connection address.</p><p><strong>The dashboard did not come back after applying a restore?</strong> Check that it runs under a supervisor, then start it manually. The swap happens at start, nothing else is needed.</p>',66)])])}const w=t(h,[["render",p]]);export{y as __pageData,w as default};
